/// Standard fields. Names follow docs/14 §3 where it lists them (`card*`); the rest are the core
/// names (spec question 2).
enum StdField {
  /// Title.
  title,

  /// Login username.
  username,

  /// Login password (secret).
  password,

  /// TOTP seed (secret).
  totpSeed,

  /// Notes.
  notes,

  /// Note body (secret, searchable).
  body,

  /// Card holder.
  cardHolder,

  /// Card number (secret).
  cardNumber,

  /// Card expiry.
  cardExpiry,

  /// Card CVV (secret).
  cardCvv,

  /// Card PIN (secret).
  cardPin,

  /// Identity first name.
  firstName,

  /// Identity middle name.
  middleName,

  /// Identity last name.
  lastName,

  /// Identity email.
  email,

  /// Identity phone.
  phone,

  /// Identity address.
  address,

  /// Identity document numbers (secret).
  ids,
}

