/// `VersionInfo`. Values are fetched with `revealVersion`.
class VersionInfo {
  /// The field.
  final StdField field;

  /// Identifies the version: the packed hybrid logical clock (milliseconds in the upper bits,
  /// a 16-bit counter below). Pass it back to `revealVersion` / `restoreVersion`.
  final PlatformInt64 hlcMs;

  /// When the version was written, ms since the Unix epoch.
  final PlatformInt64 atMs;

  /// Device name (not recorded yet; always `None`).
  final String? deviceName;

  /// This is the current version.
  final bool isCurrent;

  /// Concurrent with the current version.
  final bool concurrent;

  const VersionInfo({
    required this.field,
    required this.hlcMs,
    required this.atMs,
    this.deviceName,
    required this.isCurrent,
    required this.concurrent,
  });

  @override
  int get hashCode =>
      field.hashCode ^
      hlcMs.hashCode ^
      atMs.hashCode ^
      deviceName.hashCode ^
      isCurrent.hashCode ^
      concurrent.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VersionInfo &&
          runtimeType == other.runtimeType &&
          field == other.field &&
          hlcMs == other.hlcMs &&
          atMs == other.atMs &&
          deviceName == other.deviceName &&
          isCurrent == other.isCurrent &&
          concurrent == other.concurrent;
}

